package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.ser.std.MapSerializer;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AnyGetterWriter_getAndSerialize_TriageGen2Test {

    private AnyGetterWriter writer;

    @Mock
    private Accessor mockAccessor;

    @Mock
    private JsonGenerator mockGen;

    @Mock
    private SerializerProvider mockProvider;

    @Mock
    private MapSerializer mockMapSerializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // AnyGetterWriter is typically instantiated via internal Jackson mechanisms.
        // Since we don't have the constructor details, we use reflection to instantiate and inject private fields.
        writer = (AnyGetterWriter) sun.reflect.ReflectionFactory.getReflectionFactory()
                .newConstructorForClass(AnyGetterWriter.class, Object[].class)
                .newInstance(new Object[]{});

        setPrivateField(writer, "_accessor", mockAccessor);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetAndSerialize_ValueIsNull() throws Exception {
        Object bean = new Object();
        when(mockAccessor.getValue(bean)).thenReturn(null);

        writer.getAndSerialize(bean, mockGen, mockProvider);

        verifyNoInteractions(mockGen);
        verifyNoInteractions(mockProvider);
        verify(mockAccessor).getValue(bean);
    }

    @Test(expected = JsonMappingException.class)
    public void testGetAndSerialize_ValueIsNotMap() throws Exception {
        Object bean = new Object();
        String notAMap = "I am a string";
        when(mockAccessor.getValue(bean)).thenReturn(notAMap);
        when(mockAccessor.getName()).thenReturn("anyGetter");

        try {
            writer.getAndSerialize(bean, mockGen, mockProvider);
        } catch (JsonMappingException e) {
            assert(e.getMessage().contains("not java.util.Map"));
            throw e;
        }
    }

    @Test
    public void testGetAndSerialize_WithMapSerializer() throws Exception {
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        map.put("key", "value");

        when(mockAccessor.getValue(bean)).thenReturn(map);
        setPrivateField(writer, "_mapSerializer", mockMapSerializer);

        writer.getAndSerialize(bean, mockGen, mockProvider);

        verify(mockMapSerializer).serializeFields(map, mockGen, mockProvider);
    }

    @Test(expected = Exception.class)
    public void testGetAndSerialize_NoMapSerializerAndNotMap_ThrowsException() throws Exception {
        // This tests the branch where _mapSerializer is null and value is not a Map
        // However, the code logic checks (value instanceof Map) BEFORE checking _mapSerializer.
        // So if value is not a Map, it throws JsonMappingException regardless of _mapSerializer.

        Object bean = new Object();
        when(mockAccessor.getValue(bean)).thenReturn(123); // Integer is not a Map
        when(mockAccessor.getName()).thenReturn("testMethod");
        setPrivateField(writer, "_mapSerializer", null);

        writer.getAndSerialize(bean, mockGen, mockProvider);
    }

    @Test
    public void testGetAndSerialize_MapButNoMapSerializer_DoesNothing() throws Exception {
        // This tests the path where value is a Map, but _mapSerializer is null.
        // The code falls through the if (_mapSerializer != null) block and ends.
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();

        when(mockAccessor.getValue(bean)).thenReturn(map);
        setPrivateField(writer, "_mapSerializer", null);

        writer.getAndSerialize(bean, mockGen, mockProvider);

        verifyNoInteractions(mockMapSerializer);
        verifyNoInteractions(mockGen);
    }
}
